{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-01",
  "sketch": {
    "components": ["Nightly export job", "Customers table (source DB)", "Analytics warehouse", "Analyst query access"],
    "dataStores": ["Customers table", "Analytics warehouse"],
    "externalServices": [],
    "trustBoundaries": ["Production customer database to analytics warehouse", "Warehouse to analyst population"],
    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Every analyst can read the full customer PII set once it lands in the warehouse",
      "scenario": "The export copies the whole customers table, including emails, phone numbers and purchase history, into a warehouse where read access is granted to the entire analyst population rather than to a need-to-know group. Any analyst account (or anyone who phishes or borrows one) can select the complete customer list and purchase behaviour for every customer, enabling bulk harvesting, resale or targeted social engineering of customers.",
      "component": "Analytics warehouse access model",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "including email addresses, phone numbers and purchase history, into the analytics warehouse. All analysts have read access to the warehouse." }
      ],
      "asvs": ["V8.1.1"],
      "cwe": ["CWE-1230", "CWE-284"],
      "plainLanguage": "Everyone on the analytics team can see every customer's email, phone number and what they bought, even if they don't need it.",
      "requirement": {
        "title": "Restrict raw customer PII in the warehouse to an approved need-to-know group",
        "given": "customer records have been exported into the analytics warehouse",
        "when": "an analyst who is not in the approved PII access group queries the exported customer tables",
        "then": "the query is denied or returns only masked/tokenised values, and only members of the approved group can read raw email, phone and purchase history"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "No minimisation: direct identifiers are exported when analytics only needs aggregates",
      "scenario": "The job copies the customers table verbatim, so direct identifiers (email, phone) are duplicated into a second system with a wider audience instead of being hashed, tokenised or dropped. An attacker who gains any foothold in the warehouse, or an insider exporting a CSV, obtains a directly usable contact list linked to purchase history, which is far more damaging than the pseudonymised dataset analysts actually need.",
      "component": "Nightly export job",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "A nightly job copies the customers table, including email addresses, phone numbers and purchase history, into the analytics warehouse." }
      ],
      "asvs": [],
      "cwe": ["CWE-212", "CWE-359"],
      "plainLanguage": "The export copies real emails and phone numbers when scrambled or removed values would do the job just as well.",
      "requirement": {
        "title": "Minimise and pseudonymise identifiers in the nightly export",
        "given": "the nightly export is configured against the customers table",
        "when": "the job builds the dataset to copy",
        "then": "direct identifiers such as email and phone are omitted or replaced with a non-reversible pseudonym unless a documented analytics use case requires the raw value"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Export job credentials give standing full-table read on production customer data",
      "scenario": "The nightly job must authenticate to the production database with rights to read the entire customers table. If that credential is stored in a scheduler, CI config or script that developers or operators can read, an attacker who compromises the job host or a developer laptop reuses it to pull the whole customer base directly from production, bypassing the warehouse controls altogether.",
      "component": "Nightly export job credentials",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "A nightly job copies the customers table" }
      ],
      "asvs": [],
      "cwe": ["CWE-522", "CWE-798"],
      "plainLanguage": "The password the nightly job uses can read every customer record, so stealing it is as good as stealing the database.",
      "requirement": {
        "title": "Scope and protect the export job's database identity",
        "given": "the nightly export authenticates to the production customer database",
        "when": "the job runs",
        "then": "it uses a dedicated, read-only, short-lived credential limited to the exported columns, held in a secret store and not readable by developers or stored in job configuration"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Bulk reads of exported customer PII cannot be attributed to an individual analyst",
      "scenario": "Because warehouse read access is granted collectively to analysts, a person who downloads the full customer list can later deny it and the team cannot tell whose session did it. Without per-identity query attribution over the exported PII tables, insider exfiltration is undetectable and unprovable, and breach notification cannot scope which customers were exposed.",
      "component": "Analytics warehouse query access",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "All analysts have read access to the warehouse." }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "If someone copies the whole customer list out of the warehouse, nobody can prove who did it.",
      "requirement": {
        "title": "Attribute and alert on large reads of exported customer PII",
        "given": "the exported customer tables exist in the warehouse",
        "when": "a named analyst identity queries or exports those tables",
        "then": "the identity, timestamp, query and row volume are recorded in a tamper-resistant log and unusually large reads raise an alert"
      }
    },
    {
      "stride": "Tampering",
      "title": "Warehouse copy of customer data drifts from source with no integrity or completeness check",
      "scenario": "Each night the job overwrites or appends the customer dataset. A partial failure, a truncated copy, or a manipulated row in the warehouse goes unnoticed because nothing compares the copy against the source. Analysts and any downstream decisions (campaigns, revenue reporting) then act on data an attacker or a broken run has silently altered, and deletions or opt-outs in the source may never propagate.",
      "component": "Nightly export job to warehouse",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "A nightly job copies the customers table, including email addresses, phone numbers and purchase history, into the analytics warehouse." }
      ],
      "asvs": [],
      "cwe": ["CWE-345"],
      "plainLanguage": "Nothing checks that the copied data matches the real data, so a bad or tampered-with run can go unnoticed.",
      "requirement": {
        "title": "Verify completeness of each nightly export run",
        "given": "a nightly export run has finished",
        "when": "the warehouse dataset is published to analysts",
        "then": "row counts and checksums are compared against the source, the run is rejected and alerted on mismatch, and records deleted in the source are removed from the warehouse copy"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Exported PII accumulates in the warehouse with no retention limit",
      "scenario": "Nightly snapshots of customer contact details and purchase history build up indefinitely in a system whose purpose is analysis, not customer service. The exposure from any future warehouse compromise, misconfigured share or departing analyst grows every night, and customers who are deleted or who withdraw consent in the source system remain in historical snapshots.",
      "component": "Analytics warehouse customer dataset",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "A nightly job copies the customers table, including email addresses, phone numbers and purchase history, into the analytics warehouse." }
      ],
      "asvs": [],
      "cwe": ["CWE-359"],
      "plainLanguage": "Copies of customer data pile up in the warehouse forever, so there is more to lose every day.",
      "requirement": {
        "title": "Apply a retention limit to exported customer snapshots",
        "given": "nightly customer snapshots are stored in the analytics warehouse",
        "when": "a snapshot exceeds the agreed retention period, or a customer is deleted in the source system",
        "then": "the identifying data is purged or irreversibly anonymised automatically and the purge is recorded"
      }
    }
  ]
}

